from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(6,'decouvrir-fractions','Découvrir les fractions','2 · Fractions et nombres décimaux',
'Parts égales · Numérateur · Au-delà de l’unité',
['Lire, écrire et représenter une fraction.','Écrire une fraction supérieure à 1 avec un entier et une fraction.','Encadrer une fraction entre deux entiers consécutifs.'],
['Partages équitables et division.'],[
page(1,'Des parts égales',
bloc('definition',r'Quand une unité est partagée en 8 parts égales, chaque part est un huitième, noté $\frac18$. La fraction $\frac38$ désigne 3 de ces parts. Le nombre du bas, le dénominateur, indique le partage ; celui du haut, le numérateur, compte les parts prises.'),
r'@FIG:cours-parts@',
bloc('exemple',r'Dans une tablette de 20 carreaux, chaque carreau est $\frac1{20}$ de la tablette. Dire « les trois quarts », c’est prendre 3 parts d’un partage en 4.'),
bloc('attention',r'Une fraction exige des parts égales. Si une figure est coupée en trois morceaux de tailles différentes, le morceau colorié n’est pas forcément $\frac13$ de la figure. Les parts peuvent avoir des formes différentes, à condition d’avoir la même taille.')),
page(2,'Des fractions plus grandes que 1',
bloc('propriete',r'Une fraction peut dépasser l’unité : $\frac74$, c’est 7 quarts, soit une unité entière (4 quarts) et encore 3 quarts. On écrit $\frac74=1+\frac34$. Si le numérateur dépasse le dénominateur, la fraction dépasse 1.'),
bloc('exemple',r'$\frac93=3$ : neuf tiers remplissent exactement trois unités. $\frac{13}5=2+\frac35$ : avec 13 cinquièmes, on remplit 2 unités et il reste 3 cinquièmes.'),
bloc('savoirfaire',r'Pour encadrer $\frac{11}4$ entre deux entiers : $\frac84=2$ et $\frac{12}4=3$, donc $2<\frac{11}4<3$. On cherche les paquets complets de 4 quarts.','Encadrer entre deux entiers'),
bloc('savoirfaire',r'Partager 7 galettes entre 4 enfants : chaque galette coupée en 4 donne 28 quarts, soit 7 quarts chacun. Chaque enfant reçoit $\frac74$ de galette, c’est-à-dire $1+\frac34$. La fraction écrit le résultat exact du partage.','Partager avec une fraction')),
],[
E('Lire une part',r'Quelle fraction du disque la partie colorée représente-t-elle ?',r'Le disque est partagé en 8 parts égales et 3 sont colorées : la fraction est $\res{\frac38}$.','Compter les parts du partage puis les parts prises.','assert Rational(3,8)==Rational(3,8)',figure='frac-1'),
E('Colorier une fraction',r'Reproduire la bande et colorier $\frac25$ de sa surface.',r'La bande compte 5 cases égales : on en colorie $\res2$. La version corrigée montre les deux cases colorées ; tout choix de deux cases convient.','Repérer le nombre de parts égales de la bande.','assert Rational(2,5)<1',figure='frac-2'),
E('Le bon vocabulaire',r'Pour la fraction $\frac7{10}$, donner le numérateur et le dénominateur, puis écrire en chiffres « trois quarts » et « huit sixièmes ».',r'Le numérateur est $\res7$, le dénominateur $\res{10}$. « Trois quarts » s’écrit $\res{\frac34}$ et « huit sixièmes » $\res{\frac86}$.','Le dénominateur nomme la part, le numérateur les compte.','assert Rational(7,10).p==7 and Rational(7,10).q==10 and Rational(8,6)>1'),
E('Des parts vraiment égales ?',r'La figure est coupée en trois morceaux et un morceau est coloré. Peut-on dire que la partie colorée représente $\frac13$ de la figure ? Expliquer.',r'$\res{\text{Non}}$ : les trois morceaux n’ont pas la même taille. Une fraction ne décrit un partage que si les parts sont égales. Ici le morceau coloré couvre la moitié de la figure.','Contrôler l’égalité des parts avant d’écrire une fraction.','assert Rational(1,2)!=Rational(1,3)',figure='frac-4'),
E('Au-delà de l’unité',r'Chaque disque est partagé en quarts. Écrire la fraction colorée, puis l’écrire avec un entier et une fraction plus petite que 1.',r'On compte 5 quarts colorés : $\frac54$. Un disque entier fait 4 quarts : $\res{\frac54=1+\frac14}$.','Compter les unités complètes dans les parts.','assert Rational(5,4)==1+Rational(1,4)',figure='frac-5'),
E('Entier caché',r'Écrire $\frac74$ sous la forme d’un entier et d’une fraction inférieure à 1. Que vaut $\frac93$ ?',r'$\frac74=\frac44+\frac34=\res{1+\frac34}$. Pour les tiers : $\frac93=\res3$, car $9=3\times3$.','Retirer les paquets qui font des unités entières.','assert Rational(7,4)==1+Rational(3,4) and Rational(9,3)==3'),
E('Recomposer',r'Écrire $2+\frac35$ sous la forme d’une seule fraction.',r'Deux unités font $\frac{10}5$. Avec les trois cinquièmes restants : $2+\frac35=\res{\frac{13}5}$.','Convertir les entiers dans la part demandée.','assert 2+Rational(3,5)==Rational(13,5)'),
E('Encadrer une fraction',r'Encadrer $\frac{11}4$ puis $\frac{17}5$ entre deux entiers consécutifs.',r'$\frac84=2$ et $\frac{12}4=3$ : $\res{2<\frac{11}4<3}$. De même $\frac{15}5=3$ et $\frac{20}5=4$ : $\res{3<\frac{17}5<4}$.','Chercher les multiples du dénominateur voisins du numérateur.','assert 2<Rational(11,4)<3 and 3<Rational(17,5)<4'),
E('Sept galettes pour quatre',r'Quatre enfants se partagent équitablement 7 galettes identiques. Quelle part de galette chacun reçoit-il ? L’écrire de deux façons.',r'Chaque enfant reçoit $\res{\frac74}$ de galette : une galette entière et trois quarts, soit $\res{1+\frac34}$. Contrôle : $4\times\frac74=7$ galettes.','Couper chaque galette selon le nombre d’enfants.','assert 4*Rational(7,4)==7 and Rational(7,4)==1+Rational(3,4)'),
E('Égales à un entier',r'Compléter : $\frac{\square}6=1$ ; $\frac{12}{\square}=1$ ; combien de quarts font 2 unités ?',r'Il faut autant de parts que le partage : $\res{\frac66=1}$ et $\res{\frac{12}{12}=1}$. Deux unités font $2\times4$ quarts, soit $\res{\frac84}$.','Une fraction vaut 1 quand numérateur et dénominateur sont égaux.','assert Rational(6,6)==1 and Rational(12,12)==1 and 2==Rational(8,4)'),
E('Le gâteau de la fête',r'Un gâteau est découpé en 12 parts égales. Les invités mangent 5 parts le midi et 4 parts le soir.'+Q(r'Quelle fraction du gâteau a été mangée ?',r'Quelle fraction du gâteau reste-t-il ?'),r'On a mangé $5+4=9$ parts : $\res{\frac9{12}}$ du gâteau. Il reste $12-9=3$ parts, soit $\res{\frac3{12}}$. Contrôle : $\frac9{12}+\frac3{12}=\frac{12}{12}=1$, le gâteau entier.','Compter les parts sur le même partage en 12.','assert Rational(9,12)+Rational(3,12)==1',figure='frac-11'),
E('La frise de la classe',r'Une frise compte 20 carreaux identiques. Les élèves peignent en bleu le quart de la frise. Combien de carreaux sont bleus ? Quelle fraction de la frise reste à peindre ?',r'Le quart de 20 : $20:4=\res5$ carreaux bleus. Il reste 15 carreaux, soit $\res{\frac{15}{20}}$ de la frise, les trois quarts.','Prendre une part du partage en quatre.','assert 20//4==5 and Rational(15,20)==Rational(3,4)',figure='frac-12'),
E('Des tartes en sixièmes',r'Deux tartes identiques sont coupées en sixièmes. Les convives mangent 7 parts. Écrire la fraction de tarte mangée, la comparer à 1 et l’écrire avec un entier.',r'Sept sixièmes : $\frac76$. Comme $7>6$, cette fraction $\res{\text{dépasse }1}$ : une tarte entière et un sixième, $\res{\frac76=1+\frac16}$.','Comparer le numérateur au dénominateur.','assert Rational(7,6)>1 and Rational(7,6)==1+Rational(1,6)'),
E('Dépasser 1 sans calculer',r'Sans poser de calcul, dire si chaque fraction est inférieure, égale ou supérieure à 1 : $\frac98$ ; $\frac56$ ; $\frac{12}{12}$ ; $\frac{20}{19}$.',r'$\frac98$ et $\frac{20}{19}$ sont $\res{\text{supérieures à }1}$ : le numérateur dépasse le dénominateur. $\frac56<1$ et $\frac{12}{12}=1$.','Comparer numérateur et dénominateur.','assert Rational(9,8)>1 and Rational(5,6)<1 and Rational(12,12)==1 and Rational(20,19)>1'),
E('La moitié de qui ?',r'Hugo dit : « Une demi-pizza, c’est toujours plus qu’un quart de pizza. » Léna répond : « Pas si les pizzas sont différentes ! » Qui a raison ? Expliquer.',r'$\res{\text{Léna a raison}}$ : une fraction désigne une part d’un tout précis. La moitié d’une petite pizza peut être moins grosse que le quart d’une pizza géante. Sur un même tout, en revanche, $\frac12>\frac14$.','Toujours préciser le tout dont on prend une fraction.','assert Rational(1,2)>Rational(1,4)')
],reperes=['Parts égales et vocabulaire','Fractions supérieures à 1','Encadrements et entiers cachés','Partages et fractions d’un tout'],deco='calcul')

chapitre(7,'utiliser-fractions','Utiliser et comparer les fractions','2 · Fractions et nombres décimaux',
'Demi-droite · Comparaisons · Sommes de parts',
['Placer et repérer des fractions sur une demi-droite graduée.','Comparer des fractions et compléter jusqu’à l’unité.','Additionner et soustraire des parts de même taille.'],
['Fractions, numérateur et dénominateur.'],[
page(1,'Des fractions sur la demi-droite',
bloc('propriete',r'Sur une demi-droite graduée, les fractions sont des nombres, placés entre les entiers. Si l’unité est partagée en 4, chaque pas vaut $\frac14$ : le point $\frac74$ se trouve 3 pas après 1.'),
r'@FIG:cours-droite-fractions@',
bloc('savoirfaire',r'Pour mesurer avec une bande unité : reporter la bande entière, puis utiliser ses plis en quarts pour finir. Une longueur de 2 unités et 3 quarts s’écrit $2+\frac34$, c’est-à-dire $\frac{11}4$ d’unité.','Mesurer avec des fractions'),
bloc('attention',r'Toujours lire le partage de l’unité avant de placer une fraction : $\frac32$ n’est pas au même endroit si l’unité est partagée en 2 ou en 4. Entre 0 et 1, il y a une infinité de fractions.')),
page(2,'Comparer et réunir des parts',
bloc('propriete',r'Avec le même dénominateur, les parts ont la même taille : la fraction la plus grande a le plus grand numérateur, et on peut réunir ou retirer des parts : $\frac38+\frac28=\frac58$ et $\frac7{10}-\frac4{10}=\frac3{10}$.'),
bloc('exemple',r'Avec le même numérateur, on compare la taille des parts : $\frac13>\frac14$, car partager en 3 donne de plus grandes parts que partager en 4. Donc $\frac23>\frac24$.'),
bloc('savoirfaire',r'Prendre $\frac13$ de 12 billes, c’est partager 12 en 3 : $12:3=4$ billes. Un quart de 100 mètres vaut $100:4=25$ mètres. La fraction unitaire agit comme un partage.','Prendre une part d’une quantité'),
bloc('savoirfaire',r'Il manque $\frac49$ pour aller de $\frac59$ à l’unité, car $\frac59+\frac49=\frac99=1$. Penser « combien de parts manquent ? ».','Compléter jusqu’à 1')),
],[
E('Lire sur la demi-droite',r'L’unité est partagée en quarts. Lire les fractions repérées par les points A et B.',r'Chaque pas vaut $\frac14$. A est 3 pas après 0 : $\res{A\left(\frac34\right)}$. B est 3 pas après 1 : $\res{B\left(\frac74\right)}$.','Compter les pas depuis zéro.','assert Rational(3,4)<1<Rational(7,4)',figure='fd-1'),
E('Placer des tiers',r'Sur la demi-droite graduée en tiers, placer les points $C\left(\frac23\right)$ et $D\left(\frac53\right)$.',r'C se place 2 pas après 0 et D cinq pas après 0, c’est-à-dire 2 pas après l’entier 1. Les positions figurent en vert sur le corrigé.','Avancer d’autant de pas que le numérateur.','assert Rational(5,3)==1+Rational(2,3)',figure='fd-2'),
E('Comparer à l’unité',r'Comparer chaque fraction à 1 : $\frac56$ ; $\frac76$ ; $\frac66$.',r'$\res{\frac56<1}$ : il manque un sixième. $\res{\frac76>1}$ : un sixième de trop. $\res{\frac66=1}$ exactement.','Comparer le numérateur au dénominateur.','assert Rational(5,6)<1 and Rational(7,6)>1 and Rational(6,6)==1'),
E('Même dénominateur',r'Comparer $\frac58$ et $\frac38$, puis ranger dans l’ordre croissant : $\frac45$ ; $\frac15$ ; $\frac75$.',r'Les huitièmes ont la même taille : $\res{\frac58>\frac38}$. Pour les cinquièmes : $\res{\frac15<\frac45<\frac75}$.','À parts égales, comparer les numérateurs.','assert Rational(5,8)>Rational(3,8) and Rational(1,5)<Rational(4,5)<Rational(7,5)'),
E('Une part d’une quantité',r'Calculer $\frac13$ de 12 billes, puis $\frac14$ de 100 mètres.',r'Partager 12 en 3 : $12:3=\res4$ billes. Partager 100 en 4 : $100:4=\res{25}$ mètres.','Partager la quantité selon le dénominateur.','assert 12//3==4 and 100//4==25'),
E('Réunir des parts',r'Calculer $\frac38+\frac28$, puis $\frac25+\frac35$.',r'Les parts s’ajoutent : $\res{\frac58}$. Ensuite $\frac25+\frac35=\frac55=\res1$ : l’unité est reconstituée.','Ajouter les numérateurs, garder le dénominateur.','assert Rational(3,8)+Rational(2,8)==Rational(5,8) and Rational(2,5)+Rational(3,5)==1'),
E('Retirer des parts',r'Calculer $\frac7{10}-\frac4{10}$, puis $1-\frac29$.',r'$\res{\frac7{10}-\frac4{10}=\frac3{10}}$. Pour la seconde, écrire $1=\frac99$ : $\frac99-\frac29=\res{\frac79}$.','Écrire 1 avec le dénominateur utile.','assert Rational(7,10)-Rational(4,10)==Rational(3,10) and 1-Rational(2,9)==Rational(7,9)'),
E('Compléter jusqu’à 1',r'Compléter : $\frac59+\frac{\square}9=1$, puis $\frac{\square}6+\frac16=1$.',r'Il faut 9 neuvièmes en tout : $\square=\res4$. Pour les sixièmes : $\square=\res5$, car $\frac56+\frac16=\frac66=1$.','Compter les parts manquantes.','assert Rational(5,9)+Rational(4,9)==1 and Rational(5,6)+Rational(1,6)==1'),
E('Des cinquièmes bien placés',r'L’unité est partagée en cinquièmes. Lire la fraction du point E, puis placer $F\left(1+\frac25\right)$.',r'E est 4 pas après 0 : $\res{E\left(\frac45\right)}$. F se place 2 pas après 1, c’est $\frac75$ ; sa position figure en vert.','Convertir l’écriture mixte en pas sur la droite.','assert 1+Rational(2,5)==Rational(7,5)',figure='fd-9'),
E('Quelle part est la plus grande ?',r'Comparer $\frac13$ et $\frac14$ à l’aide des bandes, puis comparer $\frac23$ et $\frac24$.',r'Partager en 3 donne des parts plus grandes que partager en 4 : $\res{\frac13>\frac14}$. En prenant deux parts de chaque : $\res{\frac23>\frac24}$. Les bandes superposées le montrent sans calcul.','À numérateur égal, le plus petit dénominateur gagne.','assert Rational(1,3)>Rational(1,4) and Rational(2,3)>Rational(2,4)',figure='fd-10'),
E('Mesurer avec une bande',r'Avec la bande unité pliée en quarts, mesurer la longueur du segment tracé.',r'La bande se reporte 2 fois en entier, puis 3 plis d’un quart complètent : la longueur vaut $\res{2+\frac34}$ d’unité, soit $\frac{11}4$.','Reporter l’unité entière avant les parts.','assert 2+Rational(3,4)==Rational(11,4)',figure='fd-11'),
E('La randonnée',r'Un sentier mesure 20 km. Le matin, le groupe parcourt le quart du sentier.'+Q(r'Quelle distance est parcourue le matin ?',r'Quelle distance reste-t-il pour l’après-midi ?'),r'Le quart de 20 km : $20:4=\res5$ km le matin. Il reste $20-5=\res{15}$ km. Contrôle : $5+15=20$ km, le sentier entier.','Calculer la part puis le reste du tout.','assert 20//4==5 and 20-5==15'),
E('Sept parts de deux tartes',r'Deux tartes identiques sont coupées en sixièmes et 7 parts sont mangées. Quelle fraction de tarte reste-t-il ?',r'Deux tartes font $\frac{12}6$. Il reste $\frac{12}6-\frac76=\res{\frac56}$ de tarte : un peu moins qu’une tarte entière.','Écrire les deux tartes en sixièmes avant de soustraire.','assert Rational(12,6)-Rational(7,6)==Rational(5,6)'),
E('La même longueur ?',r'Lila plie une bande en 2 et prend 1 part ; Noa plie la même bande en 4 et prend 2 parts. Ont-ils pris la même longueur ? Justifier avec les bandes.',r'$\res{\text{Oui}}$ : deux quarts superposés couvrent exactement une moitié, donc $\frac12=\frac24$. Deux écritures différentes peuvent désigner le même nombre.','Superposer les parts pour comparer.','assert Rational(1,2)==Rational(2,4)',figure='fd-14'),
E('Le ruban partagé',r'Un ruban de 18 m est partagé : Ana reçoit la moitié, Bilal reçoit le tiers, Chloé reçoit le reste.'+Q(r'Calculer les longueurs reçues par Ana et Bilal.',r'Quelle longueur reste-t-il pour Chloé ?'),r'Ana : $18:2=\res9$ m. Bilal : $18:3=\res6$ m. Ensemble ils prennent 15 m ; Chloé reçoit $18-15=\res3$ m. Contrôle : $9+6+3=18$ m.','Traiter chaque part unitaire comme un partage.','assert 18//2==9 and 18//3==6 and 18-9-6==3'),
],reperes=['Demi-droite et bande unité','Comparer des fractions','Sommes et différences de parts','Fraction d’une quantité et problèmes'],deco='calcul')

chapitre(8,'fractions-decimales','Fractions décimales et virgule','2 · Fractions et nombres décimaux',
'Dixièmes · Centièmes · Écriture à virgule',
['Lire et décomposer des fractions décimales.','Relier unités, dixièmes et centièmes.','Passer d’une fraction décimale à l’écriture à virgule.'],
['Fractions sur la demi-droite graduée.'],[
page(1,'Dixièmes et centièmes',
bloc('definition',r'Partager l’unité en 10 donne des dixièmes : $\frac1{10}$. Partager chaque dixième en 10 donne des centièmes : $\frac1{100}$. Une unité vaut 10 dixièmes ou 100 centièmes ; un dixième vaut 10 centièmes.'),
r'@FIG:cours-droite-dixiemes@',
bloc('exemple',r'$\frac{23}{10}=2+\frac3{10}$ : vingt-trois dixièmes remplissent 2 unités et il reste 3 dixièmes. De même, $\frac{235}{100}=2+\frac3{10}+\frac5{100}$ : on décompose rang par rang.'),
bloc('savoirfaire',r'Sur une demi-droite graduée en dixièmes, compter les pas après l’entier : le point situé 4 pas après 2 repère $2+\frac4{10}$, c’est-à-dire $\frac{24}{10}$.','Lire des dixièmes')),
page(2,'Le codage de la virgule',
bloc('definition',r'L’écriture à virgule code une somme de fractions décimales : $35{,}78$ désigne $35+\frac7{10}+\frac8{100}$. À gauche de la virgule, la partie entière ; à droite, le chiffre des dixièmes puis celui des centièmes.')+
tableau(['Nombre','dizaines','unités','dixièmes','centièmes'],[[r'$35{,}78$','3','5','7','8'],[r'$6{,}09$','','6','0','9']]),
bloc('exemple',r'$6{,}09=6+\frac9{100}$ : le zéro montre qu’il n’y a aucun dixième. Sans lui, on écrirait $6{,}9$, un nombre différent. On lit « 6 unités et 9 centièmes ».'),
bloc('attention',r'$0{,}5$ et $0{,}05$ ne désignent pas le même nombre : 5 dixièmes pour l’un, 5 centièmes pour l’autre. En revanche $2{,}30=2{,}3$ : trente centièmes font exactement trois dixièmes.'))
],[
E('Des dixièmes à lire',r'Écrire $\frac7{10}$ puis $\frac{23}{10}$ en toutes lettres, puis écrire $\frac{23}{10}$ avec un entier et une fraction.',r'« $\res{\text{sept dixièmes}}$ » et « $\res{\text{vingt-trois dixièmes}}$ ». Comme $\frac{20}{10}=2$ : $\res{\frac{23}{10}=2+\frac3{10}}$.','Chercher les unités entières dans les dixièmes.','assert Rational(23,10)==2+Rational(3,10)'),
E('Sur la demi-droite',r'L’unité est partagée en dixièmes. Lire les nombres repérés par A et B, en écriture fractionnaire.',r'A est 4 pas après 2 : $\res{A\left(\frac{24}{10}\right)}$. B est 8 pas après 2 : $\res{B\left(\frac{28}{10}\right)}$.','Compter les pas de un dixième.','assert 2+Rational(4,10)==Rational(24,10) and 2+Rational(8,10)==Rational(28,10)',figure='dec-2'),
E('Unités, dixièmes, centièmes',r'Compléter : $1=\frac{\square}{100}$ ; $\frac3{10}=\frac{\square}{100}$ ; $\frac{50}{100}=\frac{\square}{10}$.',r'Une unité vaut $\res{100}$ centièmes. Trois dixièmes font $\res{30}$ centièmes. Cinquante centièmes font $\res5$ dixièmes.','Un dixième vaut dix centièmes.','assert Rational(100,100)==1 and Rational(3,10)==Rational(30,100) and Rational(50,100)==Rational(5,10)'),
E('Vers la virgule',r'Écrire avec une virgule : $35+\frac7{10}+\frac8{100}$, puis $\frac4{10}+\frac2{100}$.',r'La partie entière est 35, puis 7 dixièmes et 8 centièmes : $\res{35{,}78}$. Le second nombre n’a pas d’unité entière : $\res{0{,}42}$.','Placer chaque chiffre à son rang.','assert 35+Rational(7,10)+Rational(8,100)==Rational("35.78") and Rational(4,10)+Rational(2,100)==Rational(".42")'),
E('Depuis la virgule',r'Décomposer $6{,}09$ puis $14{,}3$ avec des fractions décimales.',r'$6{,}09=\res{6+\frac9{100}}$ : le zéro des dixièmes ne s’écrit pas dans la somme. $14{,}3=\res{14+\frac3{10}}$.','Lire chaque chiffre avec son rang.','assert Rational("6.09")==6+Rational(9,100) and Rational("14.3")==14+Rational(3,10)'),
E('Fractions en virgule',r'Écrire avec une virgule : $\frac{45}{10}$ ; $\frac{307}{100}$ ; $\frac8{100}$.',r'$\frac{45}{10}=4+\frac5{10}=\res{4{,}5}$. $\frac{307}{100}=3+\frac7{100}=\res{3{,}07}$. $\frac8{100}=\res{0{,}08}$.','Extraire d’abord la partie entière.','assert Rational(45,10)==Rational("4.5") and Rational(307,100)==Rational("3.07") and Rational(8,100)==Rational(".08")'),
E('Le rang de chaque chiffre',r'Dans $58{,}36$, donner le chiffre des dixièmes, le chiffre des centièmes, puis la valeur du chiffre 3.',r'Le chiffre des dixièmes est $\res3$, celui des centièmes $\res6$. Le 3 est au rang des dixièmes : il vaut $\res{\frac3{10}}$.','Repérer la virgule puis compter les rangs.','assert Rational("58.36")==58+Rational(3,10)+Rational(6,100)'),
E('Deux écritures, un nombre',r'Recopier et compléter le tableau : fraction décimale et écriture à virgule de « quatre unités et sept centièmes » et de « douze dixièmes ».',r'Quatre unités et sept centièmes : $\res{\frac{407}{100}=4{,}07}$. Douze dixièmes : $\res{\frac{12}{10}=1{,}2}$ , soit une unité et deux dixièmes.','Passer par la décomposition en rangs.','assert Rational(407,100)==Rational("4.07") and Rational(12,10)==Rational("1.2")'),
E('Avec la monnaie',r'Un centime est un centième d’euro. Écrire en euros, avec une virgule : 3 euros et 45 centimes ; 275 centimes ; 8 centimes.',r'$3+\frac{45}{100}=\res{3{,}45}$ euro. $275$ centimes font $\frac{275}{100}=\res{2{,}75}$ euros. Huit centimes : $\res{0{,}08}$ euro.','Compter les centièmes d’euro.','assert 3+Rational(45,100)==Rational("3.45") and Rational(275,100)==Rational("2.75") and Rational(8,100)==Rational(".08")'),
E('Des zéros qui comptent',r'Écrire avec une virgule : cinq centièmes, puis cinq dixièmes. Ces deux nombres sont-ils égaux ?',r'Cinq centièmes : $\res{0{,}05}$. Cinq dixièmes : $\res{0{,}5}$. Ils sont $\res{\text{différents}}$ : $\frac5{10}=\frac{50}{100}$, dix fois plus que $\frac5{100}$.','Associer chaque chiffre à son rang.','assert Rational(5,100)!=Rational(5,10) and Rational(5,10)==Rational(50,100)'),
E('La grille aux cent cases',r'Une grille compte 100 cases égales ; 37 sont colorées. Écrire la fraction de la grille colorée, puis ce nombre avec une virgule. Et si on colore 3 cases de plus ?',r'$\res{\frac{37}{100}=0{,}37}$ de la grille. Avec 3 cases de plus : $\frac{40}{100}=\res{0{,}40}$, c’est-à-dire $0{,}4$ : quatre dixièmes, soit quatre colonnes entières.','Lire les centièmes directement sur la grille.','assert Rational(37,100)==Rational(".37") and Rational(40,100)==Rational(".4")',figure='dec-13'),
E('Le compteur en dixièmes',r'Un compteur affiche $45{,}8$ et augmente d’un dixième à chaque pas. Quels nombres affiche-t-il après un pas, puis après deux pas ?',r'$45{,}8$ puis $\res{45{,}9}$ puis $\res{46}$ : neuf dixièmes plus un dixième font dix dixièmes, une unité entière. Le compteur ne passe pas par « $45{,}10$ ».','Compter de dixième en dixième avec les échanges.','assert Rational("45.8")+Rational(1,10)==Rational("45.9") and Rational("45.9")+Rational(1,10)==46'),
E('Les sauts mesurés',r'Trois sauts mesurent $3{,}45$ m, $3{,}5$ m et $3{,}09$ m. Décomposer chaque mesure avec des fractions décimales, puis donner le chiffre des dixièmes de chacune.',r'$3{,}45=3+\frac4{10}+\frac5{100}$ ; $3{,}5=3+\frac5{10}$ ; $3{,}09=3+\frac9{100}$. Les chiffres des dixièmes sont $\res4$, $\res5$ et $\res0$.','Décomposer rang par rang, sans oublier les zéros.','assert Rational("3.45")==3+Rational(4,10)+Rational(5,100) and Rational("3.5")==3+Rational(5,10) and Rational("3.09")==3+Rational(9,100)'),
E('Fractions bien connues',r'Écrire $\frac12$, $\frac14$ et $\frac34$ avec une virgule, en passant par des centièmes.',r'$\frac12=\frac{50}{100}=\res{0{,}5}$ ; $\frac14=\frac{25}{100}=\res{0{,}25}$ ; $\frac34=\frac{75}{100}=\res{0{,}75}$. Ces écritures servent très souvent en calcul mental.','Convertir en centièmes avant de coder.','assert Rational(1,2)==Rational(".5") and Rational(1,4)==Rational(".25") and Rational(3,4)==Rational(".75")'),
E('Vrai ou faux ?',r'Milo affirme : « $0{,}7$, c’est 7 centièmes. » Sara affirme : « $2{,}30$ et $2{,}3$ sont égaux. » Qui a raison ? Justifier avec des fractions décimales.',r'Milo se trompe : $0{,}7=\frac7{10}=\frac{70}{100}$, soit $\res{70}$ centièmes. Sara a raison : $2{,}30=2+\frac{30}{100}=2+\frac3{10}=\res{2{,}3}$. Un zéro final à droite ne change pas le nombre ; un zéro entre deux chiffres, si.','Traduire chaque écriture en fractions décimales.','assert Rational(".7")==Rational(70,100) and Rational("2.30")==Rational("2.3")')
],reperes=['Dixièmes, centièmes et unités','Décompositions décimales','Écriture à virgule et rangs','Monnaie, mesures et bons zéros'],deco='calcul')
